sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float width;
layout(color) uniform half4 tint;
half4 effectMain(float2 coord){half4 c=image.eval(coord);float head=fract(phase);float beam=1.0-smoothstep(width,width*1.5,abs(coord.x/size.x-head));return half4(clamp(c.rgb+tint.rgb*half(beam*amount)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
